<?phpdefined('BASEPATH') or exit('No direct script access allowed');class Home extends Admin_controller{    public function __construct()    {        parent::__construct();        $this->load->model('home_model');    }    /* This is admin home view */    public function index()    {        // When user comes to dashboard in case the setup menu is opened close it        // It's obvious that the user wont use the setup menu anymore if located in the dashboard.        $this->session->set_userdata(array(            'setup-menu-open' => ''        ));        $this->load->model('departments_model');        $this->load->model('todo_model');        $data['departments'] = $this->departments_model->get();        $data['todos'] = $this->todo_model->get_todo_items(0);        // Only show last 5 finished todo items        $this->todo_model->setTodosLimit(5);        $data['todos_finished'] = $this->todo_model->get_todo_items(1);        $data['upcoming_events_next_week'] = $this->home_model->get_upcoming_events_next_week();        $data['upcoming_events'] = $this->home_model->get_upcoming_events();        $data['title'] = _l('dashboard_string');        $this->load->model('currencies_model');        $data['currencies'] = $this->currencies_model->get();        $data['base_currency'] = $this->currencies_model->get_base_currency();        $data['activity_log'] = $this->misc_model->get_activity_log();        // Tickets charts        $tickets_awaiting_reply_by_status = $this->home_model->tickets_awaiting_reply_by_status();        $tickets_awaiting_reply_by_department = $this->home_model->tickets_awaiting_reply_by_department();        $data['tickets_reply_by_status'] = json_encode($tickets_awaiting_reply_by_status);        $data['tickets_awaiting_reply_by_department'] = json_encode($tickets_awaiting_reply_by_department);        $data['tickets_reply_by_status_no_json'] = $tickets_awaiting_reply_by_status;        $data['tickets_awaiting_reply_by_department_no_json'] = $tickets_awaiting_reply_by_department;        $data['projects_status_stats'] = json_encode($this->home_model->projects_status_stats());        $data['leads_status_stats'] = json_encode($this->home_model->leads_status_stats());        $data['google_ids_calendars'] = $this->misc_model->get_google_calendar_ids();        $data['google_api_key'] = "AIzaSyAuHJ8UIHQV78WxhkqWNiGOD_2WuaJeE1Q";        $data['bodyclass'] = 'home invoices_total_manual';        $this->load->model('announcements_model');        $data['staff_announcements'] = $this->announcements_model->get();        $data['total_undismissed_announcements'] = $this->announcements_model->get_total_undismissed_announcements();        $this->load->model('projects_model');        $data['projects_activity'] = $this->projects_model->get_activity('', do_action('projects_activity_dashboard_limit', 20));        // To load js files        $data['calendar_assets'] = true;        $this->load->model('utilities_model');        $this->load->model('estimates_model');        $data['estimate_statuses'] = $this->estimates_model->get_statuses();        $this->load->model('proposals_model');        $data['proposal_statuses'] = $this->proposals_model->get_statuses();        $wps_currency = 'undefined';        if (is_using_multiple_currencies()) {            $wps_currency = $data['base_currency']->id;        }        $data['weekly_payment_stats'] = json_encode($this->home_model->get_weekly_payments_statistics($wps_currency));        $data['agents_invoices_details'] = $this->home_model->agents_invoices_details();        $data['proformal_tax'] = $this->home_model->agents_tax_details(2018, 6);        $data['total_tax'] = $this->home_model->agents_tax_details(2018);        $data['collected_tax'] = $this->home_model->agents_tax_details(2018, 2);        if (is_admin()|| has_permission('unassigned_leads', '', 'view')) {            $datatable = array();            $leads_data = $this->home_model->getLeadsDashboard('leads');            foreach ($leads_data as $key => $lead) {                $row = array();                $row[] = '<a href="' . admin_url('leads/index/' . $lead['id']) . '" target="_blank" onclick="init_lead(' . $lead['id'] . '")return false;>' . $lead['id'] . '</a>';                $row[] = '<a href="' . admin_url('leads/index/' . $lead['id']) . '" target="_blank" onclick="init_lead(' . $lead['id'] . '")return false;>' . $lead['name'] . '</a>';                $row[] = $lead['company'];                $row[] = ($lead['email'] != '' ? '<a href="mailto:' . $lead['email'] . '">' . $lead['email'] . '</a>' : '');                $row[] = ($lead['phonenumber'] != '' ? '<a href="tel:' . $lead['phonenumber'] . '">' . $lead['phonenumber'] . '</a>' : '');                if ($lead['status_name'] == null) {                    if ($lead['lost'] == 1) {                        $statusOutput = '<span class="label label-danger inline-block">' . _l('lead_lost') . '</span>';                    } elseif ($lead['junk'] == 1) {                        $statusOutput = '<span class="label label-warning inline-block">' . _l('lead_junk') . '</span>';                    }                } else {                    $statusOutput = '<span class="inline-block label label-default">' . $lead['status_name'] . '</span>';                }                $row[] = render_tags($lead['tags']);                $row[] = $statusOutput;                $datatable[] = $row;            }            $data['leads_data'] = json_encode($datatable);        }        $data['is_home'] = true;        $this->load->view('admin/home', $data);    }    //Filter for agents invoices and reciepts    public function home_sale_agent_filter()    {        if ($this->input->is_ajax_request()) {            $time_period = $this->input->post('time_period');            $time_to = $this->input->post('time_to');            $time_from = $this->input->post('time_from');            if ($time_period) {                $records = $this->home_model->agents_invoices_details($time_period);            } elseif ($time_to && $time_from) {                $records = $this->home_model->agents_invoices_details('custom', $time_from, $time_to);            } else {                $records = $this->home_model->agents_invoices_details();            }            $data = '';            $count_total_unpaid = 0;            $unpaid_invoices = 0;            $total_receipts = 0;            $total_deposited = 0;            $total_verified = 0;            $total_vat = 0;            $total_comissionable_verified = 0;            $comissionable_verified = 0;            foreach ($records as $agent_inv_detail) {                if (is_admin() || $this->session->userdata('staff_user_id') == $agent_inv_detail['staffid']) {                    $data .= '<tr>                    <td><a target="_blank" href=' . base_url() . 'admin/staff/member/' . $agent_inv_detail['staffid'] . '> ' . $agent_inv_detail['name'] . '</a></td>                    <td>' . number_format($agent_inv_detail['total_unpaid'], 2) . '</td>                    <td>' . number_format($agent_inv_detail['current_month_unpaid'], 2) . '</td>                    <td><a target="_blank" href=' . base_url() . 'admin/receipts?agent_id=' . $agent_inv_detail['staffid'] . '>' . number_format($agent_inv_detail['total_reciept'], 2) . '</a></td>                    <td><a target="_blank" href=' . base_url() . 'admin/receipts?agent_id=' . $agent_inv_detail['staffid'] . '&status=deposited >' . number_format($agent_inv_detail['deposited'], 2) . '</a></td>                    <td><a target="_blank" href=' . base_url() . 'admin/receipts?agent_id=' . $agent_inv_detail['staffid'] . '&status=verified >' . number_format($agent_inv_detail['verified'], 2) . '</a></td>                    <td>' . number_format($agent_inv_detail['total_vat'], 2) . '</td>                                        <td><a target="_blank" href=' . base_url() . 'admin/receipts?agent_id=' . $agent_inv_detail['staffid'] . '&status=verified >' . number_format(($agent_inv_detail['verified'] - $agent_inv_detail['total_vat']), 2) . '</a></td>                                        <td></td>                    <td></td>                </tr>';                    $count_total_unpaid += $agent_inv_detail['total_unpaid'];                    $unpaid_invoices += $agent_inv_detail['current_month_unpaid'];                    $total_receipts += $agent_inv_detail['total_reciept'];                    $total_deposited += $agent_inv_detail['deposited'];                    $total_verified += $agent_inv_detail['verified'];                    $total_vat += $agent_inv_detail['total_vat'];                    $comissionable_verified = ($agent_inv_detail['verified'] - $agent_inv_detail['total_vat']);                    $total_comissionable_verified += $comissionable_verified;                }            }            if (is_admin()) {                $data .= '                    <tr>                        <td></td>                        <td><strong>' . number_format($count_total_unpaid, 2) . '</strong></td>                        <td><strong>' . number_format($unpaid_invoices, 2) . '</strong></td>                        <td><strong>' . number_format($total_receipts, 2) . '</strong></td>                        <td><strong>' . number_format($total_deposited, 2) . '</strong></td>                        <td><strong>' . number_format($total_verified, 2) . '</strong></td>                         <td><strong>' . number_format($total_vat, 2) . '</strong></td>                        <td><strong>' . number_format($total_comissionable_verified, 2) . '</strong></td>                        <td></td>                        <td></td>                    </tr>';            }            echo $data;            die();        }    }    //Filter for tax invoices , proformal and collected tax invoices    public function home_tax_agent_filter()    {        if ($this->input->is_ajax_request()) {            $year = $this->input->post('year');            $data = '';            if ($year) {                $proformal_tax = $this->home_model->agents_tax_details($year, 6);                $total_tax = $this->home_model->agents_tax_details($year);                $collected_tax = $this->home_model->agents_tax_details($year, 2);            } else {                $proformal_tax = $this->home_model->agents_tax_details(date("Y"), 6);                $total_tax = $this->home_model->agents_tax_details(date("Y"));                $collected_tax = $this->home_model->agents_tax_details(date("Y"), 2);            }            //proformal invoices            $data .= '<tr><td>Proformal Invoices</td>';            foreach ($proformal_tax as $tax_details) {                $data .= '<td>' . $tax_details["total"];                '.</td>';            }            $data .= '</tr>';            //Total Tax Invoices            $data .= '<tr><td>Tax Invoice</td>';            foreach ($total_tax as $tax_details) {                $data .= '<td>' . $tax_details["total"];                '.</td>';            }            $data .= '</tr>';            //Collected Tax Invoices            $data .= '<tr><td>Collected Tax Invoice</td>';            foreach ($collected_tax as $tax_details) {                $data .= '<td>' . $tax_details["total"];                '.</td>';            }            $data .= '</tr>';            echo $data;            die();        }    }    /* Chart weekly payments statistics on home page / ajax */    public function weekly_payments_statistics($currency)    {        if ($this->input->is_ajax_request()) {            echo json_encode($this->home_model->get_weekly_payments_statistics($currency));            die();        }    }}